UPDATE ai_plaza
plaza_id = #{plazaId}, template_id = #{templateId}, user_id = #{userId}, agent_name = #{agentName}, agent_type = #{agentType}, plaza_title = #{plazaTitle}, plaza_desc = #{plazaDesc}, like_count = #{likeCount}, favor_count = #{favorCount}, comment_count = #{commentCount},
WHERE id = #{id}

UPDATE ai_plaza
SET like_count = GREATEST(0, like_count + #{delta})
WHERE plaza_id = #{plazaId}

UPDATE ai_plaza
SET favor_count = GREATEST(0, favor_count + #{delta})
WHERE plaza_id = #{plazaId}

UPDATE ai_plaza
SET comment_count = GREATEST(0, comment_count + #{delta})
WHERE plaza_id = #{plazaId}
